fn reverse(v: &mut Vec<u64>) {
    let len = v.len();
    
    // No need to reverse if length is 0 or 1
    if len <= 1 {
        return;
    }
    
    // Swap elements from both ends moving towards the center
    for i in 0..len / 2 {
        let j = len - 1 - i;
        v.swap(i, j);
    }
}